$rows=supabase_request('GET','/rest/v1/imoveis?select=*&id=eq.'.$id.'&limit=1');$imovel=$rows[0]??null;if(!$imovel){flash('error','Imóvel não encontrado.');redirect('index.php');}
$fotos=is_array($imovel['fotos']??null)?$imovel['fotos']:[];$capa=null;$biblioteca=[];foreach($fotos as $foto){if(($foto['tipo']??'')==='capa'&&!$capa)$capa=$foto;else $biblioteca[]=$foto;}
?>
<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Editar <?=e($imovel['nome'])?></title><link rel="stylesheet" href="css/style.css"></head><body>
<main class="container pequeno"><a class="voltar" href="index.php">← Voltar</a><?php render_nav("imoveis"); ?><h1>Editar imóvel</h1><p class="subtitulo"><strong><?=e($imovel['codigo'])?></strong> · <?=e($imovel['nome'])?></p>
<?php if($error=flash('error')): ?><div class="alerta erro"><?=e($error)?></div><?php endif; ?><?php if($success=flash('success')): ?><div class="alerta sucesso"><?=e($success)?></div><?php endif; ?>
